INSERT INTO `COACH_PLAN_DETAILS` VALUES (1,12,60,NULL,12.5,'Hạ tạ chậm 3 giây, giữ khuỷu tay 45 độ để bảo vệ vai trái',1,4,5,1,'MON','Buổi 1 - Thân trên kiểm soát',1),(2,8,90,NULL,NULL,'Kéo ngực chạm xà, tránh dùng đà lắc hông',2,3,3,1,'WED','Buổi 2 - Lưng xô & Core',1),(3,15,60,NULL,20.0,'Đẩy đầu gối theo hướng mũi chân, gót chân bám sàn',3,4,4,2,'FRI','Buổi 3 - Thân dưới cân bằng',1),(4,15,45,NULL,NULL,'Thở ra đều khi nâng vai, không gồng cổ',1,3,2,1,'TUE','Buổi 1 - Kích hoạt cơ lõi nhẹ nhàng',2),(5,12,60,NULL,NULL,'Xuống tấn vừa phải theo biên độ khớp không đau',2,3,4,2,'THU','Buổi 2 - Ổn định cổ chân & khớp háng',2),(6,1,0,20,NULL,'Giữ độ dốc 1%, đi bộ sải bước thư giãn cổ chân',3,1,6,3,'SAT','Buổi 3 - Đi bộ phục hồi nhịp độ chậm',2),(7,15,45,NULL,NULL,'Siết bụng giữ thân người thành đường thẳng',1,4,1,1,'MON','Buổi 1 - Sức bền ngực & tay sau',3),(8,15,60,NULL,30.0,'Xuống sâu song song mặt sàn rồi bật lực từ gót chân',2,4,4,2,'WED','Buổi 2 - Đùi mông đốt mỡ',3),(9,1,0,25,NULL,'Luân phiên 2 phút chạy nhanh - 1 phút đi bộ hồi phục',3,1,6,3,'FRI','Buổi 3 - Chạy biến tốc HIIT',3),(10,6,90,NULL,NULL,'Treo người thả lỏng 10 giây trước mỗi hiệp kéo xà',1,3,3,1,'MON','Buổi 1 - Kéo giãn cột sống nhẹ',4),(11,12,45,NULL,NULL,'Ép sát thắt lưng dưới xuống thảm khi thực hiện',2,3,2,2,'THU','Buổi 2 - Cơ bụng bảo vệ thắt lưng',4),(12,1,0,20,NULL,'Chạy bộ nhịp độ ổn định và quay video kiểm tra dáng chạy',1,1,6,1,'SUN','Buổi tập cuối tuần',5);
