INSERT INTO `COACH_WORKOUT_PLANS` VALUES (1,'2026-10-15 08:30:00.000000','Tập trung kiểm soát nhịp thở khi hạ tạ, không khóa khớp gối ở cuối nhịp Squat.','ACTIVE','Giáo án Bổ Trợ Tăng Cơ & Ổn Định Khớp Vai','Tăng sức mạnh nhóm cơ thân trên và cải thiện biên độ vai trái','2026-10-15','2026-11-12',4,3,9906,3,'TRAINING_PLAN'),(2,'2026-10-20 09:00:00.000000','Tránh bật nhảy cường độ cao, ưu tiên động tác giãn cơ lưng dưới và thăng bằng cổ chân.','ACTIVE','Lộ Trình Yoga Phục Hồi Khớp & Cải Thiện Dẻo Dai 4 Tuần','Giảm căng cứng khớp cổ chân, tăng độ mở vai và kiểm soát hơi thở sâu','2026-10-20','2026-11-17',4,4,10,1,'TRAINING_PLAN'),(3,'2026-11-01 10:15:00.000000','Giữ lưng thẳng tự nhiên, siết cơ lõi bụng 30 giây mỗi hiệp, tăng dần mức tạ an toàn.','ACTIVE','Giáo án Siết Cơ & Đốt Mỡ Toàn Thân Tháng 11','Giảm 2.5% mỡ cơ thể và tăng sức bền tim mạch trong 4 tuần','2026-11-01','2026-11-29',4,3,19,3,'TRAINING_PLAN'),(4,'2026-11-03 14:00:00.000000','Lưu ý hạn chế gánh tạ nặng đè nén đốt sống L4-L5, ưu tiên hít xà và bài tập giãn cột sống.','ACTIVE','Bài Tập Kháng Lực Bảo Vệ Cột Sống L4-L5','Tăng sức mạnh cơ lưng xô và cơ bụng lõi mà không gây áp lực đĩa đệm','2026-11-03','2026-11-30',4,4,6,1,'TRAINING_PLAN'),(5,'2026-11-08 08:45:00.000000','Hoàn thành bài tập bổ trợ cuối tuần và quay video ngắn 20 giây gửi HLV kiểm tra kỹ thuật.','ACTIVE','Bài Tập Cardio & Sức Bền Cuối Tuần','Cải thiện ngưỡng nhịp tim vận động và sự dẻo dai toàn thân','2026-11-08','2026-11-08',1,4,21,1,'SINGLE');
