  `detail_id` int DEFAULT NULL COMMENT 'Chi tiết bài tập cụ thể trong mốc tuần/buổi (nếu có)',
  `user_id` int NOT NULL COMMENT 'Học viên nộp bài',
  `coach_id` int NOT NULL COMMENT 'Huấn luyện viên phụ trách nhận bài',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Link video thực hành (YouTube, Google Drive, TikTok, Loom, link trực tiếp...)',
  `student_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Mô tả quá trình tập, cảm nhận, thời lượng hoặc câu hỏi của học viên',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUBMITTED' COMMENT 'SUBMITTED | REVIEWED | APPROVED | REVISION_REQUESTED',
  `coach_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Nhận xét, đánh giá chuyên môn và góp ý kỹ thuật của HLV',
  `rating` int DEFAULT NULL COMMENT 'Điểm đánh giá từ HLV (1 - 5 sao)',
  `submitted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`submission_id`),
  KEY `fk_submission_user` (`user_id`),
  KEY `idx_submission_plan_user` (`plan_id`,`user_id`),
  KEY `idx_submission_coach_status` (`coach_id`,`status`),
  KEY `idx_submission_detail` (`detail_id`),
  CONSTRAINT `fk_submission_coach` FOREIGN KEY (`coach_id`) REFERENCES `USERS` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_submission_detail` FOREIGN KEY (`detail_id`) REFERENCES `COACH_PLAN_DETAILS` (`detail_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_submission_plan` FOREIGN KEY (`plan_id`) REFERENCES `COACH_WORKOUT_PLANS` (`plan_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_submission_user` FOREIGN KEY (`user_id`) REFERENCES `USERS` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
