INSERT INTO `COACH_WORKOUT_SUBMISSIONS` VALUES (1,2,4,10,4,'https://nexussport.duckdns.org/member/workout-plans','Em đã hoàn thành đủ 3 hiệp gập bụng nhẹ theo đúng nhịp thở cô hướng dẫn, cổ chân không bị nhức.','APPROVED','Tư thế cột sống và nhịp thở rất chuẩn! Tuần tới em có thể tăng thêm 3 lần mỗi hiệp.',5,'2026-11-07 09:30:00','2026-11-07 14:15:00'),(2,1,1,9906,3,'https://nexussport.duckdns.org/member/workout-plans','Nhờ thầy Tuấn kiểm tra giúp em góc hạ khuỷu tay bên vai trái ở hiệp đẩy tạ thứ 4 ạ.','REVISION_REQUESTED','3 hiệp đầu ổn nhưng sang hiệp 4 khuỷu tay trái hơi mở rộng ra ngoài. Hiệp cuối hạ nhẹ xuống 10kg để giữ chuẩn form nhé.',4,'2026-11-09 18:20:00','2026-11-10 08:10:00'),(3,5,12,21,4,'https://nexussport.duckdns.org/member/workout-plans','Em vừa chạy hoàn thành 20 phút buổi sáng, nhờ cô Mai Anh góp ý thêm về sải chân và tư thế lưng ạ.','SUBMITTED',NULL,NULL,'2026-11-11 08:40:00',NULL);
