ận được thông báo tự động.\n  - Học viên có toàn quyền lựa chọn **[Tham gia ca bù]** theo lịch mới hoặc chọn **[Bận - Hoàn lượt tập / Credit','[-0.010624448, 0.0005004869, 0.01719213, -0.01695287, -0.008052479, -0.013457515, 0.0010120757, -0.0017047398, -0.0070211883, -0.014488123, -0.01097364, 0.020825827, 0.013004955, -0.0032962728, 0.121163435, -0.0039429213, 0.012380502, 0.010546963, -0.008939224, -0.0040872265, 0.0056139855, 0.03298971, -0.0018114293, 0.0024978805, -0.020605965, 0.006065953, 0.015755285, 0.005876685, 0.024027271, -0.014528338, -0.009673288, 0.041090686, 0.008597692, -0.0025921965, 0.011525005, 0.027119467, 0.024514847, 0.003855739, -0.011131554, 0.04310923, 0.008366025, 0.02120843, 0.015030303, -0.009894968, 0.004368907, -0.016105592, 0.0027793332, -0.029152742, 0.006289016, 0.017114183, 0.0050050784, 0.00003431573, -0.003478081, -0.18596001, 0.0032518571, -0.022565257, -0.025225202, -0.013544756, -0.007889844, 0.0024667594, -0.019088166, 0.025509514, -0.0302815, 0.004652107, 0.013213041, -0.0066829897, 0.042357523, 0.028142544, -0.012178733, -0.0032790822, 0.009109915, -0.012112757, 0.0069307536, -0.011601006, -0.0014590563, 0.0125988545, 0.017533744, 0.015848767, -0.0020442798, 0.017292885, -0.0032768955, -0.0058990563, -0.0036846069, 0.01018191, 0.011188202, -0.02783287, -0.0029826774, -0.008895618, -0.019775156, 0.002480917, 0.01133183, 0.014331226, 0.015621592, 0.002324919, -0.011094074, 0.008064956, -0.01129962, 0.0077768387, 0.007315092, 0.0023156786, 0.0069985036, 0.00986089, -0.016121572, 0.0013969444, -0.004422567, 0.0005813391, -0.000991864, 0.0010987204, 0.000430686, -0.0039260145, -0.017209107, -0.019151228, 0.013997489, -0.0015283633, 0.00092512916, -0.19508344, 0.017572379, -0.016908595, 0.0005435104, 0.00097529206, -0.0053945705, 0.013819279, 0.0038687955, 0.017360533, -0.007213567, -0.009682063, 0.00615103, 0.015761878, -0.005697467, 0.002958398, 0.009107107, -0.016236864, 0.019225325, 0.005072928, 0.008850084, 0.045681, -0.012