p để duy trì áp suất thẩm thấu và sức mạnh cơ bắp.','[-0.011729055, 0.015445514, 0.02804921, -0.05651837, -0.000045903693, 0.015023639, 0.0059120497, 0.014832648, -0.03393247, -0.0020101678, -0.009207041, 0.003624869, 0.0073096394, 0.002064089, 0.10195785, 0.0078065665, 0.02081616, 0.0023330625, -0.011499626, -0.0037559585, -0.005321135, 0.0005659226, -0.0066658314, -0.0016594541, -0.03129698, -0.00012216093, 0.013176445, 0.0108622955, 0.02143088, 0.0014865084, 0.002404322, 0.018668914, 0.0322537, 0.011740415, -0.006905654, 0.004728841, -0.00055297517, -0.028318312, -0.0032877165, 0.0016300497, -0.0014001406, -0.004336444, 0.00795593, 0.01446939, -0.011206029, -0.012804239, 0.01790514, -0.015534237, 0.025430765, 0.018898334, 0.029602887, 0.015559868, -0.014803868, -0.18504663, 0.013006301, -0.021229884, -0.018724214, -0.023803867, 0.00795431, -0.010643028, -0.012783724, 0.024381112, -0.033270173, 0.0124283405, 0.003866252, -0.008453049, 0.014366001, 0.0064267186, -0.004580062, -0.010190757, -0.01801471, -0.029155834, -0.0037965216, 0.01390439, -0.006041595, 0.0021580243, -0.0047930526, 0.013105313, -0.01732222, 0.016353909, -0.0027197234, -0.030882971, -0.01154226, 0.022932237, 0.0021245142, 0.0041946135, 0.0027596152, -0.0031168805, 0.013441193, 0.013466813, -0.022078365, 0.01788754, -0.00013202375, -0.01306379, 0.00039571038, 0.01115932, 0.008161204, -0.0015414881, -0.003772514, -0.009456436, 0.0006194101, 0.00771395, 0.011563027, -0.0006619519, -0.016404811, 0.016015222, 0.007670421, 0.023154212, 0.022091275, -0.021949468, 0.0038703994, -0.03748298, 0.013379961, 0.0036610025, 0.0058284183, -0.20518053, -0.0049823606, 0.015063086, 0.010016789, 0.0042214114, -0.017961955, 0.013460422, 0.0022737312, 0.0048630685, -0.006160261, -0.009724351, -0.00945561, -0.009704196, 0.000080975384, 0.014206161, 0.0136116035, -0.0140409535, 0.00855532, 0.003565843, 0.000801374, 0.039339602, 0.010445986, -0.03178245, -0.021429483, -0.024546888, -0.012598266, 0.011293618, 0.004281634,