INSERT INTO `SCHEDULE_RESCHEDULE_REQUESTS` VALUES (46,10505,1,4,13276,'SUBSTITUTE_COACH','2026-11-02 07:00:00','2026-11-02 08:30:00',NULL,NULL,NULL,'SICK_LEAVE','HLV Trần Mai Anh bị cảm sốt nhẹ, đã thống nhất với HLV Đặng Lan Anh dạy thay ca Yoga sáng 02/11.','APPROVED','Quản lý đã phê duyệt chỉ định HLV Đặng Lan Anh dạy thay ca học.',1,'2026-11-01 15:17:48',NULL,2,'2026-11-01 13:58:52','2026-11-01 15:17:48'),(47,11222,131,13276,4,'SUBSTITUTE_COACH','2026-12-06 10:30:00','2026-12-06 12:00:00',NULL,NULL,NULL,'BUSINESS_TRIP','HLV Đặng Lan Anh đi tập huấn chuyên môn cuối tuần 06/12, kính đề nghị phân công HLV Trần Mai Anh phụ trách lớp.','APPROVED','Quản lý đã phê duyệt phân công HLV Trần Mai Anh dạy thay lớp [YOGA-107].',1,'2026-11-08 10:30:00',NULL,2,'2026-11-07 14:00:00','2026-11-08 10:30:00'),(48,10510,1,4,NULL,'MAKEUP_SESSION','2026-11-13 07:00:00','2026-11-13 08:30:00','2026-11-14 07:00:00','2026-11-14 08:30:00',2,'NO_SUBSTITUTE_SICK','HLV bị sốt siêu vi, các HLV Yoga khác đều trùng lịch ca sáng Thứ Sáu. Đề nghị dời sang sáng Thứ Bảy 14/11 phòng [P201] trống.','APPROVED','Quản lý đã phê duyệt dời lịch sang 07:00 14/11/2026 và gửi thông báo xác nhận tới học viên.',1,'2026-11-09 09:15:25','2026-11-13 20:00:00',2,'2026-11-09 08:30:00','2026-11-09 09:15:25'),(49,14008,1,4,NULL,'MAKEUP_SESSION','2026-11-13 07:00:00','2026-11-13 08:30:00','2026-11-14 14:00:00','2026-11-14 15:30:00',2,'NO_SUBSTITUTE_SICK','HLV bị sốt xuất huyết đột xuất, đã liên hệ HLV Tuấn và Lan Anh nhưng đều bận kín ca. Kính đề nghị dời sang chiều Thứ Bảy 14/11 phòng Yoga [P201] trống.','PENDING',NULL,NULL,NULL,'2026-11-13 18:00:00',2,'2026-11-10 08:30:00','2026-11-10 08:30:00'),(50,14011,3,3,NULL,'MAKEUP_SESSION','2026-11-15 17:30:00','2026-11-15 19:00:00','2026-11-16 10:30:00','2026-11-16 12:00:00',1,'NO_SUBSTITUTE_EMERGENCY','HLV gia đình có việc khẩn tại quê, không tìm được HLV thay thế tối Chủ nhật. Kính đề nghị dời ca Gym sang sáng Thứ Hai 16/11 (10:30) phòng [P101] trống.','PENDING',NULL,NULL,NULL,'2026-11-15 12:00:00',2,'2026-11-10 09:15:00','2026-11-10 09:15:00'),(51,10577,7,4,NULL,'MAKEUP_SESSION','2026-11-14 08:45:00','2026-11-14 10:15:00','2026-11-15 08:45:00','2026-11-15 10:15:00',2,'NO_SUBSTITUTE_OTHER','Xin dời ca sáng Thứ Bảy sang sáng Chủ nhật do trùng lịch khám sức khỏe định kỳ.','REJECTED','Từ chối do khung giờ 08:45 Chủ nhật tại phòng [P201] đã có lớp [YOGA-103] khác hoạt động. Vui lòng chọn khung giờ chiều trống.',1,'2026-11-08 11:00:00',NULL,2,'2026-11-08 08:20:00','2026-11-08 11:00:00');
