INSERT INTO `SUBJECTS` VALUES (1,'Thể Hình (Gym)','Tập tạ tự do và máy móc hiện đại',NULL,90,NULL,'ACTIVE'),(2,'Yoga Căn Bản','Yoga thư giãn và giãn cơ buổi sáng',NULL,90,NULL,'ACTIVE'),(3,'Zumba Dance','Nhảy theo nhạc Latin sôi động giảm mỡ',NULL,90,NULL,'ACTIVE'),(4,'Bơi Lội','Kỹ thuật bơi ếch, bơi sải chuyên nghiệp',NULL,90,NULL,'ACTIVE'),(5,'Đạp Xe (Spinning)','Đạp xe cường độ cao trên nền nhạc',NULL,90,NULL,'ACTIVE'),(6,'Boxing & Kickfit','Võ thuật đối kháng kết hợp rèn luyện sức bền, phản xạ và tự vệ thực chiến',NULL,90,NULL,'ACTIVE'),(7,'Pilates Reformer','Tập luyện kiểm soát cơ lõi toàn thân và phục hồi vóc dáng trên thiết bị máy chuyên dụng',NULL,90,NULL,'ACTIVE');
