INSERT INTO `SUPPORT_REQUESTS` VALUES (90,10,2,'COACH_FEEDBACK',NULL,'Góp ý HLV: Phương pháp giảng dạy & Truyền đạt','[Khía cạnh góp ý: Phương pháp giảng dạy & Truyền đạt | Lớp học liên quan: [YOGA-102] Yoga Giảm Cân & Thon Gọn Vóc Dáng (HLV Trần Mai Anh)] Cô Mai Anh hướng dẫn điều chỉnh nhịp thở và sửa tư thế rất tận tâm. Kính mong trung tâm mở thêm khung giờ chiều.','ESCALATED','NORMAL',NULL,NULL,NULL,'2026-11-11 19:20:00','2026-11-11 19:20:00'),(91,19,1,'COACH_FEEDBACK',NULL,'Phản ánh về sự đúng giờ & tác phong huấn luyện','[Khía cạnh góp ý: Đúng giờ & Tác phong chuyên nghiệp | Lớp học liên quan: [YOGA-101] Yoga Giãn Cơ & Phục Hồi Khớp (HLV Trần Mai Anh)] Kính đề nghị bộ phận chuyên môn nhắc nhở bắt đầu khởi động đúng 07:00 để học viên đủ thời gian giãn cơ cuối buổi.','ESCALATED','NORMAL',NULL,NULL,NULL,'2026-11-10 10:15:00','2026-11-10 10:15:00'),(92,6,3,'COACH_FEEDBACK',NULL,'Đánh giá tích cực về hướng dẫn kỹ thuật tạ của HLV Tuấn','[Khía cạnh góp ý: Chuyên môn kỹ thuật & Chỉnh sửa tư thế | Lớp học liên quan: [GYM-101] Gym Căn Bản & Tăng Cơ Cho Nam (HLV Nguyễn Văn Tuấn)] Thầy Tuấn sửa form Squat và Deadlift rất kỹ, giúp em cải thiện đau lưng rõ rệt sau 3 tuần tập.','RESOLVED','NORMAL','Quản lý trung tâm đã ghi nhận phản hồi tích cực và gửi lời khen thưởng định kỳ tháng 11 tới HLV Nguyễn Văn Tuấn.',1,'2026-11-08 16:00:00','2026-11-07 09:30:00','2026-11-08 16:00:00'),(93,19,3,'CLASS_CANCELLATION','CASH_REFUND','Hủy lớp [GYM-101] Gym Căn Bản & Xin hoàn tiền do chuyển công tác','[Lý do: Đột xuất giữa khóa / Sức khỏe / Đổi chỗ ở] Em nhận quyết định điều động công tác vào TP.HCM từ tuần tới nên không thể theo học tiếp các buổi còn lại. Kính nhờ trung tâm hỗ trợ hoàn phần học phí chưa học.','PENDING','HIGH',NULL,NULL,NULL,'2026-11-11 08:30:00','2026-11-11 08:30:00'),(94,7,2,'CLASS_CANCELLATION','ISSUE_CREDIT','Xin hủy lớp [YOGA-102] & nhận mã Credit bảo lưu học phí','[Lý do: Thay đổi lịch làm việc cá nhân] Công ty em chuyển ca làm sang buổi sáng nên không theo được lịch 07:00. Xin hủy lớp để nhận mã Credit đăng ký lớp buổi tối.','PENDING','HIGH',NULL,NULL,NULL,'2026-11-11 19:50:00','2026-11-11 19:50:00'),(95,19,5,'CLASS_CANCELLATION','CASH_REFUND','Hủy lớp [ZUMBA-101] và hoàn học phí qua chuyển khoản ngân hàng','[Lý do: Sức khỏe chấn thương cổ chân] Em có giấy chỉ định nghỉ vận động mạnh 3 tuần từ bác sĩ, xin bảo lưu hoàn tiền qua ngân hàng.','ESCALATED','HIGH','Lễ tân đã xác minh giấy khám và chuyển Quản lý trung tâm duyệt chi hoàn tiền qua tài khoản ngân hàng.',2,'2026-11-09 10:15:00','2026-11-08 20:00:00','2026-11-09 10:15:00'),(96,9906,1,'CLASS_CANCELLATION','ISSUE_CREDIT','Xin hủy lớp [YOGA-101] & nhận mã Credit bảo lưu 100%','[Lý do: Đổi lịch trực bệnh viện] Em kẹt lịch trực viện cố định tháng 11 nên xin đổi sang mã Credit để chọn lớp cuối tuần.','RESOLVED','HIGH','Đã duyệt hủy lớp và cấp mã tín dụng CR-NX-2026-9906 trị giá 300.000đ vào ví hội viên.',2,'2026-11-05 14:00:00','2026-11-05 10:00:00','2026-11-05 14:00:00'),(97,21,6,'CLASS_CANCELLATION','ISSUE_CREDIT','Bảo lưu học phí lớp [SWIM-101] sang khóa tháng sau','[Lý do: Công tác ngắn hạn 2 tuần] Xin cấp mã tín dụng bảo lưu phần học phí còn lại lớp Bơi Sải.','APPROVED','HIGH','Đã cấp mã tín dụng CR-NX-2026-21 trị giá 600.000đ (hạn dùng đến 31/12/2026).',2,'2026-11-04 11:20:00','2026-11-04 09:00:00','2026-11-04 11:20:00'),(98,6,1,'FACILITY_ISSUE',NULL,'Điều hòa phòng [P201] Studio Yoga bị rò nước và thổi lạnh','[Khu vực: Phòng tập Studio / Yoga | Thiết bị: Điều hòa góc trái P201] Sáng nay ca 07:00 máy lạnh bị nhỏ nước xuống thảm tập số 4-5, nhờ bộ phận kỹ thuật kiểm tra.','PENDING','HIGH',NULL,NULL,NULL,'2026-11-11 08:45:00','2026-11-11 08:45:00'),(99,11,4,'FACILITY_ISSUE',NULL,'Đệm lưng máy tập Leg Press phòng [P101] bị bong chỉ','[Khu vực: Khu máy tập Gym | Thiết bị: Máy Leg Press số 2] Phần đệm da bị hở mép, đề xuất bọc lại để đảm bảo an toàn khi đẩy tạ nặng.','RESOLVED','HIGH','Bộ phận kỹ thuật đã thay mới đệm da máy Leg Press số 2 vào sáng 07/11/2026.',2,'2026-11-07 10:30:00','2026-11-06 18:10:00','2026-11-07 10:30:00'),(100,8,5,'SCHEDULE_SUPPORT',NULL,'Xin hỗ trợ chuyển ca [ZUMBA-101] sang buổi tối cuối tuần','[Loại hỗ trợ: Yêu cầu chuyển giờ học | Chi tiết: Tuần 12/11 - 20/11] Tuần tới em tăng ca thứ 2-4-6, nhờ Lễ tân tư vấn lớp Zumba lịch Thứ 7/Chủ nhật.','PENDING','NORMAL',NULL,NULL,NULL,'2026-11-11 14:20:00','2026-11-11 14:20:00'),(101,19,133,'SCHEDULE_SUPPORT',NULL,'Chuyển lớp tự động: [ZUMBA-101] ➔ [ZUMBA-202] Zumba Đốt Mỡ Cường Độ Cao Hi-Lo','Hội viên xác nhận chuyển từ lớp [ZUMBA-101] sang lớp [ZUMBA-202] phù hợp khung giờ rảnh mới.','APPROVED','NORMAL','Hệ thống đã hoàn tất chuyển lịch học sang lớp [ZUMBA-202] và gửi thông báo tới hội viên.',2,'2026-10-28 09:00:00','2026-10-28 08:50:00','2026-10-28 09:00:00'),(102,12,NULL,'COMPLAINT',NULL,'Góp ý bổ sung thêm tủ locker khu vực Bể bơi Tầng 1','[Mảng góp ý: Cơ sở tiện ích chung] Giờ cao điểm 17:30 tủ đồ khu bể bơi thường kín chỗ, mong trung tâm bố trí thêm dãy tủ dự phòng.','PENDING','NORMAL',NULL,NULL,NULL,'2026-11-10 18:15:00','2026-11-10 18:15:00'),(103,10,NULL,'GENERAL_INQUIRY',NULL,'Hỏi về chính sách gia hạn sớm Thẻ Gym 1 Năm và ưu đãi hạng Gold','Em sắp hết hạn gói 3 tháng, nếu nâng cấp lên Thẻ Gym 1 Năm trước khi hết hạn có được cộng dồn ngày và hưởng giảm giá 10% hạng Gold không?','PENDING','NORMAL',NULL,NULL,NULL,'2026-11-11 11:05:00','2026-11-11 11:05:00');
