DROP TABLE IF EXISTS `TRAINEE_ASSESSMENTS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TRAINEE_ASSESSMENTS` (
  `assessment_id` int NOT NULL AUTO_INCREMENT,
  `coach_id` int NOT NULL,
  `user_id` int NOT NULL,
  `schedule_id` int DEFAULT NULL,
  `booking_id` int DEFAULT NULL,
  `plan_id` int DEFAULT NULL,
  `assessment_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight` decimal(5,2) DEFAULT NULL,
  `height` decimal(5,2) DEFAULT NULL,
  `body_fat_percentage` decimal(4,1) DEFAULT NULL,
  `muscle_mass` decimal(5,2) DEFAULT NULL,
  `performance_rating` int DEFAULT NULL,
  `attendance_rating` int DEFAULT NULL,
  `feedback_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommendation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`assessment_id`),
  KEY `idx_assessment_user` (`user_id`,`created_at`),
  KEY `idx_assessment_coach` (`coach_id`,`created_at`),
  KEY `fk_assessment_schedule` (`schedule_id`),
  KEY `fk_assessment_booking` (`booking_id`),
  KEY `fk_assessment_plan` (`plan_id`),
  CONSTRAINT `fk_assessment_booking` FOREIGN KEY (`booking_id`) REFERENCES `BOOKINGS` (`booking_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_assessment_coach` FOREIGN KEY (`coach_id`) REFERENCES `USERS` (`user_id`),
  CONSTRAINT `fk_assessment_plan` FOREIGN KEY (`plan_id`) REFERENCES `COACH_WORKOUT_PLANS` (`plan_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_assessment_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `SCHEDULES` (`schedule_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_assessment_user` FOREIGN KEY (`user_id`) REFERENCES `USERS` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

