INSERT INTO `USER_CREDITS` VALUES (121,9906,96,NULL,'CR-NX-2026-9906',300000.00,300000.00,'Hoàn phí hủy lớp [YOGA-101] - Bảo lưu 100% quyền lợi','2026-12-31','ACTIVE',NULL,'2026-11-05 14:00:00'),(122,21,97,NULL,'CR-NX-2026-21',600000.00,600000.00,'Bảo lưu học phí lớp [SWIM-101] sang khóa tháng sau','2026-12-31','ACTIVE',NULL,'2026-11-04 11:20:00'),(123,10,NULL,NULL,'CR-NX-2026-10',450000.00,450000.00,'Mã tín dụng ưu đãi gia hạn hội viên thân thiết Tháng 11','2026-12-31','ACTIVE',NULL,'2026-11-01 09:00:00'),(124,19,95,NULL,'CR-NX-2026-19',900000.00,900000.00,'Tín dụng bảo lưu học phí khóa Thể hình & Zumba','2026-12-31','ACTIVE',NULL,'2026-11-07 16:30:00'),(125,6,NULL,NULL,'CR-NX-2026-06',250000.00,0.00,'Mã tín dụng ưu đãi tháng 10 (đã sử dụng thanh toán khóa học)','2026-12-31','USED',NULL,'2026-10-20 09:00:00');
