  `duration_days_snapshot` int DEFAULT NULL,
  `price_snapshot` decimal(10,2) DEFAULT NULL,
  `type_name_snapshot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description_snapshot` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `terms_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
