  CONSTRAINT `user_memberships_ibfk_2` FOREIGN KEY (`package_id`) REFERENCES `PACKAGES` (`package_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11154 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
